"""Report conditional, per-leg force comparisons without empirical-validation claims."""
from pathlib import Path
import json,csv,hashlib
import numpy as np
from scipy.optimize import linprog
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from tension_reference import reaction_cone
ROOT=Path(__file__).resolve().parents[1]
GROUPS={'Vasti':('vasint_','vaslat_','vasmed_'),'Rectus femoris':('recfem_',),'Gluteus maximus':('glmax',),'Hamstrings':('bflh_','bfsh_','semimem_','semiten_'),'Soleus':('soleus_',),'Gastrocnemius':('gasmed_','gaslat_')}
def main():
 out=ROOT/'deliverables/yun_muscle_comparison_review';out.mkdir(exist_ok=True);cases={};metrics={};bounds=[]
 for key,rel in [('Jump','results/muscle_validation/yun_common_published_v2/jump'),('Squat','results/muscle_validation/yun_common_published_v1/squat')]:
  folder=ROOT/rel;s=json.loads((folder/'tension_summary.json').read_text());z=dict(np.load(folder/'tensions.npz'));names=s['names'];t=z['times'];F=z['force_N'];coords=s['coordinate_names'];keep=[i for i,n in enumerate(coords) if not n.startswith('mtp_angle_')];metrics[key]={}
  assert s['root_force_residual_max_N']<.1*87*9.80665 and s['root_moment_residual_max_Nm']<.1*87*9.80665*1.78
  cases[key]=dict(folder=rel,summary=s,data=z,names=names)
  for group,stems in GROUPS.items():
   ids=[i for i,n in enumerate(names) if n.endswith('_r') and n.startswith(stems)];history=F[:,ids].sum(1);j=int(history.argmax());metrics[key][group]=dict(peak_N=float(history[j]),peak_s=float(t[j]),mean_N=float(np.trapezoid(history,t)/(t[-1]-t[0])),integral_Ns=float(np.trapezoid(history,t)),duration_s=float(t[-1]-t[0]),elements=[names[i] for i in ids]);ref=z['reference_N'];R=z['R'][j,keep];tau=z['target'][j,keep];passive=z['passive'][j];C,b=reaction_cone(z['S'][j],z['offset'][j],z['axes'][j],20.,16);obj=np.zeros(len(names));obj[ids]=ref[ids];A=R*ref;sc=np.maximum(np.linalg.norm(A,axis=1),1.);Aub=C*ref;us=np.maximum(np.linalg.norm(Aub,axis=1),1.);kw=dict(A_eq=A/sc[:,None],b_eq=(tau-R@passive)/sc,A_ub=Aub/us[:,None],b_ub=(b-C@passive)/us,bounds=(0,None),method='highs');low=linprog(obj,**kw);high=linprog(-obj,**kw)
   bounds.append(dict(case=key,group=group,time_s=float(t[j]),selected_N=float(history[j]),minimum_balanced_force_N=float(low.fun+passive[ids].sum()) if low.success else None,maximum_balanced_force_N=float(-high.fun+passive[ids].sum()) if high.success else None,upper_bound_status=high.message,interpretation='Feasibility range at the selected-peak frame; not a biological confidence interval.'))
  rows=[]
  for i,name in enumerate(names):
   if name.startswith('scapular_contact_'):continue
   f=F[:,i];rows.append(dict(element=name,peak_N=float(f.max()),peak_s=float(t[f.argmax()]),mean_N=float(np.trapezoid(f,t)/(t[-1]-t[0])),integral_Ns=float(np.trapezoid(f,t)),passive_peak_N=float(z['passive'][:,i].max())))
  with (out/(key.lower()+'_individual_muscles.csv')).open('w',newline='',encoding='utf-8-sig') as h:w=csv.DictWriter(h,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 fig,ax=plt.subplots(1,2,figsize=(12,5),layout='constrained');groups=list(GROUPS);y=np.arange(len(groups))
 for k,(label,color) in enumerate([('Jump','#40bcb0'),('Squat','#f2ab60')]):
  for a,metric,unit in [(ax[0],'peak_N','Peak tension [kN]'),(ax[1],'integral_Ns','Tension integral [kN s]')]:a.barh(y+(k-.5)*.32,[metrics[label][g][metric]/1000 for g in groups],.30,label=label,color=color);a.set(yticks=y,yticklabels=groups,xlabel=unit);a.invert_yaxis();a.grid(axis='x',alpha=.2)
 ax[0].legend();fig.suptitle('MODEL DIAGNOSTIC | right leg | jump propulsion vs 240 kg squat ascent',fontsize=12);fig.savefig(out/'comparison.png',dpi=160);plt.close(fig)
 fig,axs=plt.subplots(3,2,figsize=(11,9),layout='constrained')
 for a,(group,stems) in zip(axs.flat,GROUPS.items()):
  for label,color in [('Jump','#279e94'),('Squat','#ce812b')]:
   z=cases[label]['data'];names=cases[label]['names'];ids=[i for i,n in enumerate(names) if n.endswith('_r') and n.startswith(stems)];a.plot(z['times']-z['times'][0],z['force_N'][:,ids].sum(1)/1000,label=label,color=color)
  a.set(title=group,xlabel='Time from propulsion/ascent start [s]',ylabel='Tension [kN]');a.grid(alpha=.2)
 axs[0,0].legend();fig.suptitle('Conditional force histories | true time scales | right leg');fig.savefig(out/'force_histories.png',dpi=150);plt.close(fig)
 report=dict(status='conditional_comparison_requires_anatomical_and_motion_validation',height_m=1.78,mass_kg=87,box_height_m=1.6,squat_bar_kg=240,metrics=metrics,feasible_ranges=bounds,scope='Jump ground propulsion only versus squat ascent only; flight, landing and descent excluded.',force_definition='Sum of simultaneously evaluated scalar muscle-tendon tensions per anatomical group, right leg. Not sum of separately timed peaks; not a net joint reaction.',normalization='Peak in N and N/(87*9.80665), integral in N s. No strength capacity or activation inferred.',assumptions=['Generic attachments, segment inertias and rigid-tendon architecture.','MyoSim paths with exact Catelli patella splines; remaining deep-flexion path differences are unresolved.','Seth/RMR registered scapular paths, generic passive curves, 20-degree GH reaction cone.','One normalized-force magnitude/continuity solution, lambda=.002; no force ceiling or prescribed antagonist floor.','Intrinsic foot/fascia forces omitted; MTP support moments reported separately.'],numerical_checks={k:dict(moment_balance_max_Nm=c['summary']['checks']['moment_balance_max_error'],root_force_residual_max_N=c['summary']['root_force_residual_max_N'],root_moment_residual_max_Nm=c['summary']['root_moment_residual_max_Nm'],NE_max_SI=c['summary']['NE_crosscheck_max_SI'],source_motion_sha256=c['summary']['source_motion_sha256']) for k,c in cases.items()},human_force_accuracy_validated=False,athlete_specific_measurement=False,force_clipping=False,references=[dict(title='Hicks et al. 2015: simulation verification and validation',url='https://pmc.ncbi.nlm.nih.gov/articles/PMC4321112/'),dict(title='Purzel et al. 2025: elite-powerlifter muscle forces',url='https://pubmed.ncbi.nlm.nih.gov/40275729/',use='Vasti dominance is qualitatively consistent; no numerical acceptance range extracted.'),dict(title='Wade et al. 2018: jumping and Achilles estimates',url='https://pmc.ncbi.nlm.nih.gov/articles/PMC5797114/',use='Protocol differs. Achilles estimate is not identical to a scalar calf-muscle sum.'),dict(title='OpenSim high-flexion model release notes',url='https://raw.githubusercontent.com/opensim-org/opensim-models/master/Models/Rajagopal/README.txt',use='Updated paths and passive properties matter; increasing ROM alone is insufficient.')],release_decision='Do not publish athlete-specific muscle-force percentages or claim 10% force accuracy yet. Numerical balance passes, anatomical magnitude and motion validation remain open.')
 for values in metrics.values():
  for value in values.values():value['peak_BW']=value['peak_N']/(87*9.80665)
 (out/'comparison_audit.json').write_text(json.dumps(report,indent=2));table=''.join(f'<tr><td>{g}</td><td>{metrics["Jump"][g]["peak_N"]/1000:.2f}</td><td>{metrics["Squat"][g]["peak_N"]/1000:.2f}</td><td>{metrics["Jump"][g]["integral_Ns"]/1000:.2f}</td><td>{metrics["Squat"][g]["integral_Ns"]/1000:.2f}</td></tr>' for g in GROUPS)
 html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Jump / squat: muscle review</title><style>body{max-width:1100px;margin:auto;padding:24px;background:#101b2a;color:#e5eef7;font:16px/1.6 system-ui}a{color:#72ded2}img{max-width:100%;background:white}table{border-collapse:collapse;width:100%}td,th{padding:10px;border-bottom:1px solid #405166;text-align:left}.note{background:#342b25;padding:18px}small{color:#bbcadb}</style><h1>160 cm box jump / 240 kg squat</h1><p>178 cm · 87 kg · right leg · same anatomy and force-sharing rule</p><div class="note"><b>Model diagnostic — individual muscle-force magnitudes are not yet validated.</b><br>Ground propulsion and squat ascent only. A 160 cm box is not 160 cm of COM flight rise. Do not interpret this as measured Yun Sung-bin performance.</div><img src="comparison.png"><table><tr><th>Muscle group</th><th>Jump peak kN</th><th>Squat peak kN</th><th>Jump kN·s</th><th>Squat kN·s</th></tr>'''+table+'''</table><p>Peak and time integral answer different questions. Each group sums simultaneous forces; left and right are not combined. Tension integral is not work, fatigue or physiological dose.</p><img src="force_histories.png"><details open><summary>Verification and unresolved questions</summary><p>Independent Newton–Euler consistency, muscle moment balance and native length/virtual-work derivatives pass numerical checks. These do not establish anatomical or person-specific force accuracy.</p><p>The native deep-flexion patella polynomial was replaced by the source Catelli spline and all velocities/accelerations were recalculated. Remaining knee wrapping/joint-path differences still affect force magnitude. Several model-selected values are high enough to require further cross-model and matched-motion validation.</p><p>Without a strength ceiling or identified co-contraction, moment balance permits many muscle-force solutions; some upper feasibility bounds are unbounded. The plotted solution is selected by a declared regularizer.</p><p>Neutral wrists and moderate arm-swing candidates have not yet passed a stable full landing. The previous released motion is preserved, not replaced by a failed trial.</p></details><p><a href="comparison_audit.json">Full audit and references</a> · <a href="jump_individual_muscles.csv">Jump: individual muscles</a> · <a href="squat_individual_muscles.csv">Squat: individual muscles</a> · <a href="../yun_160_box_jump_review/index.html">Previous full-cycle motion</a></p></html>'''
 (out/'index.html').write_text(html,encoding='utf-8');print('COMPARISON_REVIEW',json.dumps(dict(status=report['status'],metrics=metrics)),flush=True)
if __name__=='__main__':main()
